import pandas as pd


def _differs(a, b):
    """NULL-aware inequality: NULL vs NULL -> not differs; NULL vs non-NULL -> differs;
    non-NULL vs non-NULL -> standard inequality."""
    a_null = pd.isna(a)
    b_null = pd.isna(b)
    if a_null and b_null:
        return False
    if a_null != b_null:
        return True
    return a != b


def _pick_latest(group: pd.DataFrame) -> pd.Series:
    max_date = group['update_date'].max()
    candidates = group[group['update_date'] == max_date]
    if len(candidates) == 1:
        return candidates.iloc[0]
    # Tie-break: greater (email, tier) lexicographic pair wins.
    candidates = candidates.sort_values(by=['email', 'tier'], ascending=[False, False])
    return candidates.iloc[0]


def _get_input(inputs: dict, name: str) -> pd.DataFrame:
    """Case-insensitive lookup of an input relation by name."""
    if name in inputs:
        return inputs[name]
    lname = name.lower()
    for k, v in inputs.items():
        if k.lower() == lname:
            return v
    raise KeyError(name)


def run(inputs: dict) -> dict:
    dim = _get_input(inputs, 'DIM_ACCT').copy()
    stg = _get_input(inputs, 'STG_ACCT').copy()

    cols = ['acct_id', 'email', 'tier', 'eff_start_date', 'eff_end_date', 'is_current']
    for c in cols:
        if c not in dim.columns:
            dim[c] = None

    # --- Step 1: Dedup STG_ACCT to latest per acct_id by update_date,
    #     ties broken by greater (email, tier) lexicographic pair.
    if len(stg) == 0:
        stg_dedup = stg.copy()
    else:
        stg_dedup = (
            stg.groupby('acct_id', as_index=False, group_keys=False)
               .apply(_pick_latest)
               .reset_index(drop=True)
        )

    # Working mutable representation of DIM_ACCT rows.
    work = dim.to_dict('records')

    stg_list = stg_dedup.to_dict('records')

    for s in stg_list:
        acct_id = s['acct_id']
        s_email = s.get('email')
        s_tier = s.get('tier')
        s_date = s.get('update_date')

        # Find the current row for this acct_id (is_current == 1), if any.
        current_idx = None
        for i, r in enumerate(work):
            if r['acct_id'] == acct_id and r.get('is_current') == 1:
                current_idx = i
                break

        if current_idx is None:
            # No current row exists - insert new current version.
            new_row = {
                'acct_id': acct_id,
                'email': s_email,
                'tier': s_tier,
                'eff_start_date': s_date,
                'eff_end_date': None,
                'is_current': 1,
            }
            work.append(new_row)
        else:
            c = work[current_idx]
            tier_changed = _differs(c.get('tier'), s_tier)
            email_changed = _differs(c.get('email'), s_email)

            if tier_changed:
                # Expire current row at s.update_date.
                c['eff_end_date'] = s_date
                c['is_current'] = 0

                # Insert new current version.
                new_row = {
                    'acct_id': acct_id,
                    'email': s_email,
                    'tier': s_tier,
                    'eff_start_date': s_date,
                    'eff_end_date': None,
                    'is_current': 1,
                }
                work.append(new_row)

            if email_changed:
                # Retro-overwrite email across ALL rows (history and current)
                # for this acct_id, including any freshly inserted row.
                for r in work:
                    if r['acct_id'] == acct_id:
                        r['email'] = s_email

    out = pd.DataFrame(work, columns=cols)

    return {'dim_acct_out': out}
